INSERT INTO public.site_settings (key,value,tipe) VALUES
('nama_situs','SMART PKL','text'),
('tagline','Sistem Pendukung Keputusan Pemilihan & Rekomendasi Tempat PKL','text'),
('nama_perusahaan_host','PT Seven Inc.','text'),
('deskripsi_singkat','Platform pengambilan keputusan berbasis metode SMART untuk mencocokkan mahasiswa dengan mitra PKL terbaik secara objektif dan transparan.','text'),
('email_kontak','pkl-support@seveninc.co.id','text'),
('telepon_kontak','+62 821-3456-7890','text'),
('alamat_kontak','Jl. Ringroad Utara No. 7, Sleman, D.I. Yogyakarta','text'),
('teks_footer','© 2026 PT Seven Inc. Hak cipta dilindungi undang-undang. Bersama membangun generasi profesional yang disiplin dan kompeten.','text'),
('quote_login','Disiplin hari ini, kesuksesan esok hari.','text'),
('cms_hero','{"id":"hero-1","judul":"Penilaian Kedisiplinan & Kinerja Mahasiswa PKL Metode SMART","subjudul":"Didukung metode ilmiah SMART (Simple Multi Attribute Rating Technique) yang objektif, transparan, dan mempertimbangkan kesesuaian prodi, fasilitas, reputasi, hingga prospek karier.","teks_tombol_utama":"Lihat Hasil & Peringkat Mahasiswa","link_tombol_utama":"#hasil-peringkat","teks_tombol_sekunder":"Jelajahi Mitra PKL","link_tombol_sekunder":"/tempat-pkl","gambar_url":""}','json'),
('cms_fitur','[{"id":"f-1","ikon":"Calculator","judul":"Algoritma SMART Transparan","deskripsi":"Menghitung nilai utilitas benefit dan cost secara matematis serta membuka rincian rumus ke mahasiswa tanpa kotak hitam.","urutan":1,"aktif":true},{"id":"f-2","ikon":"SlidersHorizontal","judul":"Kustomisasi Bobot Preferensi","deskripsi":"Mahasiswa dapat menyesuaikan skala prioritas pribadi (misal mengutamakan jarak dekat atau uang saku) secara interaktif.","urutan":2,"aktif":true},{"id":"f-3","ikon":"Building2","judul":"Database Mitra Terverifikasi","deskripsi":"Informasi lengkap profil perusahaan, kuota penerimaan, alamat, kontak HRD, dan bidang spesialisasi kerja.","urutan":3,"aktif":true},{"id":"f-4","ikon":"FileCheck","judul":"Pengajuan PKL Terintegrasi","deskripsi":"Ajukan lamaran magang langsung dari hasil rekomendasi terbaik dan pantau proses verifikasi admin secara real-time.","urutan":4,"aktif":true},{"id":"f-5","ikon":"BarChart3","judul":"Visualisasi & Export Hasil","deskripsi":"Dilengkapi grafik perbandingan skor alternatif serta fitur ekspor laporan ke format PDF dan spreadsheet siap cetak.","urutan":5,"aktif":true},{"id":"f-6","ikon":"ShieldCheck","judul":"Keamanan Berbasis Role (RBAC)","deskripsi":"Pemisahan hak akses yang tegas antara mahasiswa dan tim admin pengelola data akademik menggunakan Supabase RLS.","urutan":6,"aktif":true}]','json'),
('cms_langkah','[{"id":"l-1","nomor":1,"judul":"Buat Akun & Lengkapi Profil","deskripsi":"Daftarkan diri dengan NIM, program studi, angkatan, dan kontak aktif Anda."},{"id":"l-2","nomor":2,"judul":"Atur Bobot Prioritas Anda","deskripsi":"Gunakan slider untuk menyesuaikan seberapa penting kesesuaian prodi, jarak, atau fasilitas bagi Anda."},{"id":"l-3","nomor":3,"judul":"Hitung & Analisis Hasil SMART","deskripsi":"Lihat peringkat tempat PKL paling cocok lengkap dengan rincian perhitungan utilitas matematis."},{"id":"l-4","nomor":4,"judul":"Kirim Pengajuan ke Mitra","deskripsi":"Pilih mitra peringkat teratas Anda dan ajukan PKL untuk ditinjau oleh koordinator kampus."}]','json'),
('cms_faq','[{"id":"faq-1","pertanyaan":"Apa itu metode SMART dalam pemilihan tempat PKL?","jawaban":"SMART (Simple Multi Attribute Rating Technique) adalah metode pengambilan keputusan multikriteria yang mengevaluasi setiap alternatif berdasarkan pembobotan nilai utilitas (benefit dan cost) untuk menghasilkan skor akhir yang objektif.","urutan":1,"aktif":true},{"id":"faq-2","pertanyaan":"Apakah saya bisa mengubah bobot kriteria sesuai kebutuhan sendiri?","jawaban":"Ya. Sistem menyediakan slider kustomisasi bobot di mana Anda dapat memprioritaskan kriteria tertentu, seperti memperbesar bobot jarak dekat jika tidak memiliki kendaraan pribadi.","urutan":2,"aktif":true},{"id":"faq-3","pertanyaan":"Bagaimana cara menentukan kriteria bertipe Benefit dan Cost?","jawaban":"Kriteria Benefit (seperti Relevansi Prodi, Fasilitas, Reputasi) adalah kriteria yang nilainya semakin besar semakin menguntungkan. Kriteria Cost (seperti Jarak Tempuh) adalah kriteria yang nilainya semakin kecil semakin menguntungkan.","urutan":3,"aktif":true},{"id":"faq-4","pertanyaan":"Berapa jumlah tempat PKL yang bisa saya ajukan dalam satu periode?","jawaban":"Mahasiswa dapat mengajukan 1 mitra PKL aktif sekaligus agar proses penempatan tertib dan kuota mitra tidak terkunci ganda.","urutan":4,"aktif":true},{"id":"faq-5","pertanyaan":"Apakah hasil perhitungan SMART otomatis mengikat penempatan PKL?","jawaban":"Hasil SMART berfungsi sebagai rekomendasi ilmiah penunjang keputusan. Persetujuan akhir tetap dikoordinasikan oleh tim akademik dan ketersediaan kuota resmi dari mitra terkait.","urutan":5,"aktif":true},{"id":"faq-6","pertanyaan":"Bagaimana jika kriteria atau alternatif tempat PKL berubah?","jawaban":"Admin dapat memperbarui data kriteria, bobot standar, maupun daftar mitra kapan saja melalui panel Dashboard Admin.","urutan":6,"aktif":true}]','json'),
('cms_testimoni','[{"id":"t-1","nama":"Bagus Wicaksono","jabatan":"Alumni PKL - Software Engineering","instansi":"Ditempatkan di Gojek Tech Hub","isi":"Metode SMART sangat membantu saya menemukan tempat PKL yang sesuai dengan minat backend engineering. Berkat rekomendasi akurat ini, saya langsung ditawari kontrak kerja setelah lulus!","aktif":true},{"id":"t-2","nama":"Nabila Putri, S.Kom","jabatan":"Koordinator Magang & Kerjasama Industri","instansi":"Fakultas Ilmu Komputer","isi":"Sistem ini memangkas waktu seleksi dan komplain penempatan mahasiswa hingga 80%. Prosesnya adil, terbuka, dan didukung bukti perhitungan yang kuat.","aktif":true},{"id":"t-3","nama":"Hendra Gunawan","jabatan":"Head of People & Culture","instansi":"PT Seven Inc.","isi":"Mahasiswa yang magang di tempat kami melalui sistem ini memiliki kecocokan kompetensi yang jauh lebih tinggi dengan kebutuhan proyek riil industri kami.","aktif":true}]','json'),
('cms_pengumuman','[{"id":"p-1","judul":"Pembukaan Pendaftaran PKL Periode 1 - 2025","kategori":"Pendaftaran","tanggal":"15 Januari 2025","isi":"Pendaftaran dan pengajuan tempat PKL Periode 1 resmi dibuka hingga 28 Februari 2025. Harap segera melengkapi profil dan menjalankan perhitungan SMART.","dipublikasi":true},{"id":"p-2","judul":"Penambahan Kuota Mitra Industri PT Seven Inc. & Telkom","kategori":"Mitra","tanggal":"22 Januari 2025","isi":"Kabar gembira! Kuota mahasiswa untuk divisi Software Engineering dan Digital Marketing di PT Seven Inc. dan PT Telkom bertambah sebanyak 5 kursi.","dipublikasi":true},{"id":"p-3","judul":"Sosialisasi Tata Tertib dan Logbook Harian PKL","kategori":"Panduan","tanggal":"01 Februari 2025","isi":"Seluruh mahasiswa yang telah disetujui pengajuannya wajib mengikuti pembekalan daring via Zoom pada hari Sabtu, 8 Februari 2025 pukul 09.00 WIB.","dipublikasi":true}]','json'),
('cms_menu','[{"id":"m-1","label":"Penilaian & Peringkat PKL","path":"/","role_akses":"semua","urutan":1,"aktif":true},{"id":"m-2","label":"Dashboard Admin","path":"/admin","role_akses":"admin","urutan":2,"aktif":true}]','json')
